const KEY='little-garden.design-prototype.v1';
const day=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const QUESTIONS=[['어젯밤 잠은 어땠나요?',['많이 힘들었어요','조금 뒤척였어요','그냥 그래요','괜찮게 잤어요']],['지금 에너지는 어떤가요?',['매우 낮음','낮음','보통','괜찮음','충분함']],['오늘 식사는 어땠나요?',['거의 못 먹었어요','조금 먹었어요','평소와 비슷해요','든든하게 먹었어요']],['지금 기분은 어떤가요?',['많이 지쳐요','조금 무거워요','잔잔해요','괜찮아요','가벼워요']]];
const CARES=[{id:'water',icon:'drop',title:'물 한 컵',copy:'몸에 물을 조금 채워줘요.',meta:'1분 · 아주 쉬움',past:'물을 마셨어요'},{id:'sky',icon:'cloud',title:'하늘 바라보기',copy:'잠깐, 창밖에 눈을 쉬어줘요.',meta:'2분 · 아주 쉬움',past:'하늘을 봤어요'},{id:'walk',icon:'walk',title:'5분 걷기',copy:'가까운 곳을 천천히 걸어요.',meta:'5분 · 쉬움',past:'산책했어요'}];
const paths={back:'<path d="m14 6-6 6 6 6"/>',leaf:'<path d="M12 21V10M12 15C5 15 4 10 4 7c5 0 8 3 8 8Zm0-3c0-6 4-8 8-8 0 5-3 8-8 8Z"/>',note:'<rect x="5" y="3" width="14" height="18" rx="3"/><path d="M9 8h6M9 12h6M9 16h4"/>',drop:'<path d="M12 3S6 10 6 15a6 6 0 0 0 12 0c0-5-6-12-6-12Z"/>',cloud:'<path d="M7 18h10a4 4 0 0 0 0-8A6 6 0 0 0 6 11a3.5 3.5 0 0 0 1 7Z"/>',walk:'<circle cx="13" cy="4" r="2"/><path d="m10 21 2-6-2-3 2-4 3 3 3 1M7 14l3-2m5 9-3-6"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.leaf}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function load(){try{const data=JSON.parse(localStorage.getItem(KEY)||'{"records":{}}');if(!data.records||typeof data.records!=='object')return {records:{}};for(const [date,r] of Object.entries(data.records)){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!r||r.date!==date||!Array.isArray(r.answers)||r.answers.length!==4||r.answers.some((a,i)=>!QUESTIONS[i][1].includes(a))||!Array.isArray(r.cares)||r.cares.some(id=>!CARES.some(c=>c.id===id))||!['low','normal'].includes(r.state)||typeof r.note!=='string')delete data.records[date];}return data;}catch{return {records:{}};}}
let data=load(),view='home',step=0,answers=[],note='',selectedCare=null,feedback='',runtime=null,animationTimer=null;
const media=matchMedia('(prefers-reduced-motion: reduce)');let paused=media.matches;
const current=()=>data.records[day()]||null;
function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));data=next;return true;}catch{return false;}}
const top=(title,back=true)=>`<header class="top">${back?`<button class="icon-btn" data-action="back" aria-label="뒤로 가기">${icon('back')}</button>`:'<span></span>'}<h2>${title}</h2><span></span></header>`;
const plant=(state='normal',live=false)=>`<button class="character" ${live?'data-action="touch"':'tabindex="-1"'} aria-label="식물 반응 보기"><img src="./${state}.png" width="500" height="500" alt="원본 Rive 식물 캐릭터"><canvas ${live?'id="rive-canvas"':''} width="680" height="680" aria-hidden="true"></canvas></button>`;
const nav=active=>`<nav class="bottom" aria-label="주요 메뉴"><button data-view="home" class="${active==='home'?'active':''}" ${active==='home'?'aria-current="page"':''}>${icon('leaf')}정원</button><button data-view="garden" class="${active==='garden'?'active':''}" ${active==='garden'?'aria-current="page"':''}>${icon('note')}기록</button></nav>`;
const mood=r=>!r?'오늘의 나를 가볍게 살펴볼까요?':r.state==='low'?'조금 지쳐 보여요.':'오늘은 기분이 괜찮은 날이네요.';
function calendar(records,sample=false){const now=sample?new Date(2026,8,13):new Date(),y=now.getFullYear(),m=now.getMonth(),length=new Date(y,m+1,0).getDate(),offset=(new Date(y,m,1).getDay()+6)%7;return `<div class="calendar"><h3>${y}년 ${m+1}월</h3><div class="week">${['월','화','수','목','금','토','일'].map(x=>`<span>${x}</span>`).join('')}</div><div class="days">${'<span></span>'.repeat(offset)}${Array.from({length},(_,i)=>{const d=i+1,key=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,marked=sample?[10,11,12,13].includes(d):!!records[key];return `<span class="day ${marked?'mark':''}" aria-label="${m+1}월 ${d}일${marked?' 기록 있음':''}">${d}</span>`;}).join('')}</div><p class="small" style="margin-top:20px">기록하지 않은 날도 정원은 기다려요.</p></div>`;}
function screen(which,live=false,sample=false){const r=sample?{state:'low',cares:[],answers:[],note:''}:current(),state=r?.state||'normal';
if(which==='onboarding')return `<section class="screen onboard"><div class="scene">${plant('normal',live)}</div><h2>오늘의 나를<br>만나러 가볼까요?</h2><p>작은 정원에서<br>천천히 나를 돌봐요.</p><button class="primary" data-view="home" style="margin-top:48px">시작하기 ${icon('arrow')}</button><p class="small" style="margin-top:16px">천천히 시작해도 괜찮아요.</p></section>`;
if(which==='home')return `<section class="screen">${top('오늘의 정원',false)}<div class="scene"><span class="date">${new Intl.DateTimeFormat('ko',{month:'long',day:'numeric',weekday:'long'}).format(new Date())}</span>${plant(state,live)}</div><div class="mood"><span class="kicker">오늘의 모습</span><h2>${mood(r)}</h2><p>${r?.state==='low'?'오늘은 천천히 가도 괜찮아요.':'잠깐, 나에게 안부를 물어봐요.'}</p></div><button class="primary" data-view="checkin">${icon('note')}${r?'오늘의 나 기록 확인하기':'오늘의 나 기록하기'}</button><div class="trace">${icon('leaf')}<div><strong>${r?'오늘도 나를 한 번 살펴봤어요.':'작은 시작도 충분해요.'}</strong>${r?'이 시간은 정원에 조용히 남아요.':'좋은 날도, 지친 날도 있는 그대로요.'}</div></div>${nav('home')}</section>`;
if(which==='checkin'){const s=sample?1:step,opts=QUESTIONS[Math.min(s,3)][1],a=sample?'낮음':answers[s];return `<section class="screen">${top('오늘의 나')}<div class="progress"><span>${Math.min(s+1,4)} / 4</span><div class="track" role="progressbar" aria-label="오늘의 나 기록" aria-valuemin="0" aria-valuemax="4" aria-valuenow="${Math.min(s+1,4)}"><i style="width:${Math.min(s+1,4)*25}%"></i></div><span>약 30초</span></div><div class="question"><span class="kicker">${s<4?'지금의 나에게 안부를 물어요':'마지막으로, 선택 사항이에요'}</span><h2 tabindex="-1">${s<4?QUESTIONS[s][0]:'오늘을 한마디로<br>남겨볼까요?'}</h2><p>${s<4?'가장 가까운 것을 골라주세요.':'잘 정리된 문장이 아니어도 괜찮아요.'}</p>${s<4?`<div class="choices" role="group" aria-label="${QUESTIONS[s][0]}">${opts.map(o=>`<button class="choice" data-answer="${o}" aria-pressed="${a===o}"><span>${o}</span><span class="circle">${a===o?icon('check'):''}</span></button>`).join('')}</div><button class="primary" data-action="next" ${a?'':'disabled style="opacity:.5"'}>다음 ${icon('arrow')}</button>`:`<label for="daily-note">오늘의 한마디 <span class="small">(선택)</span></label><textarea id="daily-note" maxlength="120" placeholder="마음에 남은 순간을 적어보세요.">${esc(note)}</textarea><p class="small" id="note-count">${note.length} / 120</p><button class="primary" data-action="save">오늘의 나를 살펴봤어요</button><button class="text-btn" data-action="skip-note" style="width:100%">건너뛰어도 괜찮아요.</button>`}<div id="form-error" role="alert"></div></div><p class="small" style="margin-top:auto;padding-top:40px">있는 그대로의 오늘이면 충분해요.</p></section>`;}
if(which==='care'){const count=r?.cares.length||0;return `<section class="screen">${top('오늘의 작은 돌봄')}<div class="care-head"><span class="kicker">오늘의 나를 살펴봤어요.</span><h2>${state==='low'?'오늘은 조금<br>지친 날이네요.':'오늘의 괜찮은 기분을<br>천천히 이어가요.'}</h2><p>아주 작은 것 하나만 해볼까요?</p></div><div class="care-hero">${plant(count===3?'complete':state,live)}</div><div class="care-list">${CARES.map(c=>{const done=r?.cares.includes(c.id),selected=selectedCare===c.id;return `<article class="care-card ${done?'done':selected?'selected':''}"><div class="care-icon">${icon(c.icon)}</div><div><h3>${c.title}</h3><p>${c.copy}</p><span>${c.meta}</span></div><button data-care="${c.id}" ${done?'disabled':''}>${done?'완료 ✓':selected?'완료했어요':'해볼게요'}</button></article>`;}).join('')}</div>${count===3?'<div class="completion"><h2>오늘의 나를 위해<br>세 가지를 해냈어요.</h2><p>나를 돌본 시간이 하나 더 남았어요.</p></div>':''}<p class="status" role="status" aria-live="polite">${feedback}</p><button class="text-btn" data-view="home">${count?'정원으로 돌아가기':'오늘은 쉬어가도 괜찮아요.'}</button></section>`;}
const entries=Object.values(data.records).sort((a,b)=>b.date.localeCompare(a.date));return `<section class="screen">${top('나의 정원',false)}<div class="section-copy"><span class="kicker">나를 살핀 시간</span><h2>조금씩 나를<br>돌봤어요.</h2><p>자주 오지 않아도, 남긴 시간은 그대로예요.</p></div>${calendar(data.records,sample)}<h3 style="font-size:17px;margin:8px 0">작은 돌봄의 흔적</h3><div class="journal">${sample?['9/13|하늘을 봤어요','9/12|물을 마셨어요','9/11|산책했어요','9/10|다시 찾아왔어요'].map((e,i)=>`<div><time>${e.split('|')[0]}</time>${icon(CARES[i%3].icon)}<span>${e.split('|')[1]}</span></div>`).join(''):entries.length?entries.slice(0,10).map(e=>`<div><time>${e.date.slice(5).replace('-','/')}</time>${icon('leaf')}<span>${e.cares.length?e.cares.map(id=>CARES.find(c=>c.id===id).past).join(' · '):'오늘의 나를 살펴봤어요'}</span></div>`).join(''):'<p class="small" style="padding:24px 0">아직 남긴 기록이 없어요.<br>첫 안부부터 천천히 시작해요.</p>'}</div><div class="trace">${icon('leaf')}<p>기분이 좋아서가 아니라,<br>나를 살핀 시간이 쌓여요.</p></div>${nav('garden')}</section>`;}
function cleanup(){clearTimeout(animationTimer);runtime?.cleanup();runtime=null;}
function playFeedback(name){if(!runtime||paused)return;runtime.stop();runtime.play(name);const duration=name==='통통'?2350:name==='new_leaf 뿅'?2250:1000;clearTimeout(animationTimer);animationTimer=setTimeout(()=>{if(!runtime)return;runtime.stop();runtime.play(current()?.state==='low'?'low_energy':'idle');},duration);}
function initRive(event){const canvas=document.querySelector('#rive-canvas');if(!canvas||paused||!window.rive)return;rive.RuntimeLoader.setWasmUrl('./rive.wasm');const baseline=current()?.state==='low'&&view!=='onboarding'?'low_energy':'idle';const inst=new rive.Rive({src:'./plant-original.riv',canvas,artboard:'Artboard 1',animations:baseline,autoplay:true,layout:new rive.Layout({fit:rive.Fit.Contain,alignment:rive.Alignment.Center}),onLoad:()=>{if(runtime!==inst)return;inst.resizeDrawingSurfaceToCanvas();canvas.parentElement.classList.add('loaded');if(event)playFeedback(event);},onLoadError:()=>{canvas.parentElement.classList.remove('loaded');}});runtime=inst;}
function render(event){cleanup();document.querySelector('#prototype').innerHTML=screen(view,true);initRive(event);document.querySelector('#motion-toggle').setAttribute('aria-pressed',String(paused));document.querySelector('#motion-toggle').textContent=paused?'모션 재생하기':'모션 멈추기';}
function go(target,replace=false,event){data=load();view=target==='care'&&!current()?'checkin':target;if(!['home','onboarding','checkin','care','garden'].includes(view))view='home';if(view==='checkin'){step=0;answers=[...(current()?.answers||[])];note=current()?.note||'';}feedback='';selectedCare=null;history[replace?'replaceState':'pushState']({},'',`#${view}`);render(event);document.querySelector('#prototype h2')?.setAttribute('tabindex','-1');document.querySelector('#prototype h2')?.focus({preventScroll:true});}
function saveCheckin(skip){if(answers.length!==4||answers.some((a,i)=>!QUESTIONS[i][1].includes(a)))return;const isNew=!current();const record={date:day(),answers:[...answers],note:skip?'':note,state:answers.some((a,i)=>QUESTIONS[i][1].indexOf(a)<2)?'low':'normal',cares:current()?.cares||[]};if(!persist({records:{...data.records,[day()]:record}})){document.querySelector('#form-error').innerHTML='<p class="error">저장하지 못했어요. 내용을 유지했으니 다시 시도해 주세요.</p>';return;}go('care',true,isNew?'new_leaf 뿅':undefined);}
document.querySelector('#prototype').addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.view){go(b.dataset.view);return;}if(b.dataset.answer){answers[step]=b.dataset.answer;render();document.querySelector(`[data-answer="${CSS.escape(b.dataset.answer)}"]`)?.focus();return;}if(b.dataset.care){if(!current()){go('checkin',true);return;}const id=b.dataset.care;if(selectedCare!==id){selectedCare=id;render();return;}const old=current();if(old.cares.includes(id))return;const updated={...old,cares:[...old.cares,id]};if(!persist({records:{...data.records,[day()]:updated}})){feedback='저장하지 못했어요. 잠시 후 다시 시도해 주세요.';render();return;}selectedCare=null;feedback=updated.cares.length===3?'오늘의 나를 위해 세 가지를 해냈어요.':'오늘 나를 조금 돌봤어요.';render(updated.cares.length===3?'통통':'잎만 통통');return;}switch(b.dataset.action){case'back':if(view==='checkin'&&step>0){step--;render();}else go('home');break;case'next':if(answers[step]){step++;render();document.querySelector('.question h2')?.focus();}break;case'save':saveCheckin(false);break;case'skip-note':saveCheckin(true);break;case'touch':playFeedback('touch');break;}});
document.querySelector('#prototype').addEventListener('input',e=>{if(e.target.id==='daily-note'){note=e.target.value;document.querySelector('#note-count').textContent=`${note.length} / 120`;}});
document.querySelectorAll('[data-demo]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.demo)));
document.querySelector('#motion-toggle').addEventListener('click',()=>{paused=!paused;render();});media.addEventListener('change',()=>{paused=media.matches;render();});
function sync(){data=load();const target=location.hash.slice(1)||'home';if(target==='care'&&!current())go('checkin',true);else{view=['home','care','garden','onboarding','checkin'].includes(target)?target:'home';render();}}
addEventListener('popstate',sync);addEventListener('hashchange',sync);addEventListener('pageshow',sync);addEventListener('storage',e=>{if(e.key===KEY||e.key===null)sync();});document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync();else runtime?.pause();});setInterval(()=>{if(view==='care'&&!current())go('checkin',true);},30000);addEventListener('resize',()=>runtime?.resizeDrawingSurfaceToCanvas());
document.querySelector('#board').innerHTML=['onboarding','home','checkin','care','garden'].map((s,i)=>`<article><div class="board-label">0${i+1} / ${['Onboarding','오늘의 정원','오늘의 나 기록','작은 돌봄','나의 정원'][i]}</div><div class="phone" inert>${screen(s,false,true)}</div></article>`).join('');
document.querySelector('#swatches').innerHTML=[['Paper','#F7F5EE'],['Surface','#FFFDF8'],['Forest','#3F5D46'],['Ink','#293D32'],['Muted','#626E63'],['Sage','#DFE8DC']].map(([n,c])=>`<div class="token"><div class="swatch" style="background:${c}"></div><strong>${n}</strong>${c}</div>`).join('');
document.querySelector('#states').innerHTML=[['Normal','normal','idle'],['LowEnergy','low','low_energy'],['Complete','complete','통통 · 원본 반짝임'],['Growing','growing','new_leaf 뿅']].map(([n,p,a])=>`<article class="state"><img src="./${p}.png" alt="${n} 원본 애니메이션 프레임" width="500" height="500" loading="lazy"><h3>Plant / ${n}</h3><p>${a}</p></article>`).join('');
go('onboarding',true);

